<?php

use PHPUnit\Framework\TestCase;

// Ajusta la ruta según tu estructura de proyecto real
require_once __DIR__ . '/../src/factorial.php'; 

class FactorialTest extends TestCase {

    public function testFactorialDeCeroDebeRetornarUno(): void {
        $this->assertEquals(1, factorial(0));
    }

    public function testFactorialDeUnoDebeRetornarUno(): void {
        $this->assertEquals(1, factorial(1));
    }

    public function testFactorialDeCincoDebeRetornarCientoVeinte(): void {
        $this->assertEquals(120, factorial(5));
    }

    public function testFactorialDeDiezDebeRetornarTresMillonesSeiscientosVeintiochoMilOchocientosOcho(): void {
        $this->assertEquals(3628800, factorial(10));
    }

    public function testFactorialDeNumeroNegativoLanzaExcepcion(): void {
        $this->expectException(\InvalidArgumentException::class);
        $this->expectExceptionMessage('No se puede calcular el factorial de un número negativo.');

        factorial(-1);
    }

    public function testFactorialDeNumerosGrandesNoRompeElFlujo(): void {
        // 15! = 1.307.674.368.000 (cabe en int64)
        $this->assertEquals(1307674368000, factorial(15));
    }
}
```

